import{_ as t,c as r,o as n,a2 as a}from"./chunks/framework.Bfq10Vlj.js";const p=JSON.parse('{"title":"Docs","description":"","frontmatter":{"aliases":["docs/"],"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/documentation","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/docs/_index.md","to":"_index.md"},"redirectUrl":"/documentation/home","title":"Docs","prev":false,"next":false},"headers":[],"relativePath":"docs/_index.md","filePath":"docs/_index.md","lastUpdated":null}'),o={name:"docs/_index.md"};function i(s,e,d,u,l,c){return n(),r("div",null,e[0]||(e[0]=[a('<h1 id="gardener-documentation" tabindex="-1">Gardener Documentation <a class="header-anchor" href="#gardener-documentation" aria-label="Permalink to &quot;Gardener Documentation&quot;">​</a></h1><h2 id="first-steps-with-gardener" tabindex="-1">First Steps with Gardener <a class="header-anchor" href="#first-steps-with-gardener" aria-label="Permalink to &quot;First Steps with Gardener&quot;">​</a></h2><p>If you&#39;re new to Gardener, we recommend starting with our <a href="/docs/getting-started/">Getting Started</a> guide to understand the basic concepts.</p><p>For an easy to grasp analogy of how Gardener works, check out <a href="/docs/getting-started/podrick-and-the-infinite-garden/">Podrick and the Infinite Garden</a>.</p><h2 id="understanding-the-documentation-personas" tabindex="-1">Understanding the Documentation Personas <a class="header-anchor" href="#understanding-the-documentation-personas" aria-label="Permalink to &quot;Understanding the Documentation Personas&quot;">​</a></h2><p>Our documentation is organized around three user personas to help you find the most relevant content for your needs. Below you will find more information on each of them.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>You can switch between personas through the Documentation drop-down menu in the top navigation bar.</p></div><h3 id="user" tabindex="-1">User <a class="header-anchor" href="#user" aria-label="Permalink to &quot;User&quot;">​</a></h3><p>You are a <strong>User</strong> if you:</p><ul><li>Create and manage Kubernetes clusters (shoots) using Gardener</li><li>Work with Gardener through the Dashboard or API</li><li>Configure cluster specifications, extensions, and networking</li><li>Have access to shoot clusters but not to the underlying seed infrastructure</li></ul><p>User documentation focuses on how to use Gardener to create, configure, and manage your Kubernetes clusters.</p><h3 id="operator" tabindex="-1">Operator <a class="header-anchor" href="#operator" aria-label="Permalink to &quot;Operator&quot;">​</a></h3><p>You are an <strong>Operator</strong> if you:</p><ul><li>Run and maintain Gardener landscapes</li><li>Manage seed clusters and infrastructure</li><li>Configure Gardener components and extensions</li><li>Handle platform-level operations and monitoring</li><li>Provide Gardener as a service to end-users</li></ul><p>Operator documentation covers installation, configuration, maintenance, and operational aspects of running Gardener.</p><h3 id="developer" tabindex="-1">Developer <a class="header-anchor" href="#developer" aria-label="Permalink to &quot;Developer&quot;">​</a></h3><p>You are a <strong>Developer</strong> if you:</p><ul><li>Contribute to Gardener core components</li><li>Develop Gardener extensions or integrations</li><li>Work on the Gardener codebase</li><li>Need to understand Gardener&#39;s internal architecture and APIs</li></ul><p>Developer documentation includes architecture details, development guides, API references, and contribution guidelines.</p><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>If you need assistance or have questions:</p><ul><li><strong>Community Support</strong>: Join our <a href="/community/">community channels</a> to connect with other Gardener users and contributors</li><li><strong>GitHub Issues</strong>: Report bugs or request features in our <a href="https://github.com/gardener/documentation" target="_blank" rel="noreferrer">GitHub repository</a></li><li><strong>Slack</strong>: Join the Gardener community on <a href="https://join.slack.com/t/gardener-cloud/shared_invite/zt-33c9daems-3oOorhnqOSnldZPWqGmIBw" target="_blank" rel="noreferrer">Slack</a></li></ul>',22)]))}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
